window.kbPageData["views/entry/k-9a1be64e7f074b1c"] = {"key":"entry/k-9a1be64e7f074b1c","state":{"route":"entry/k-9a1be64e7f074b1c"},"node":{"id":"k-9a1be64e7f074b1c","mode":"k","title":"2023年中央金融工作会议的资本市场部署","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":["2023年中央金融工作会议关于资本市场枢纽、股票发行注册制和一流投行的部署"],"qs":["江苏 2024 C类 行测#4"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"2023年10月30日至31日，中央金融工作会议在北京召开，提出着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道，并部署优化融资结构。","review":{"definition":"2023年10月30日至31日，中央金融工作会议在北京召开，提出着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道，并部署优化融资结构。","explanation":"①推动股票发行注册制走深走实、③更好发挥资本市场枢纽功能、④培育一流投资银行和投资机构，都列在通稿关于优化融资结构的同一句中，②建设种类齐全的金融产品体系未列入这项部署，因此题目选C。通稿在同一句中还部署了发展多元化股权融资和提高上市公司质量，随后谈及债券市场、机构定位、市场规则和法人治理。题干的“三大重点方向”是对入选选项的归纳，通稿没有给①③④设这一合称。","references":[{"source":"web-b307fd9f3de643e2","location":"2023年10月31日通稿，高质量发展段","quote":"优化融资结构，更好发挥资本市场枢纽功能"}],"evidence":"更好发挥资本市场枢纽功能，推动股票发行注册制走深走实","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#4":{"paper":"江苏 2024 C类 行测","n":4,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",1],"asrc":["02d6b49839583bdaf297.pdf",2],"card":"98551fe75e468e8d61347276","links":[{"id":"k-9a1be64e7f074b1c","role":"直接考查","why":"会议将发挥资本市场枢纽功能、深化股票发行注册制和培育一流投资银行与投资机构纳入相关部署。"}]}},"terms":{},"references":{"web-b307fd9f3de643e2":{"name":"新华社《中央金融工作会议在北京举行》","url":"https://www.cac.gov.cn/2023-10/31/c_1700414900966626.htm"}},"topics":[],"units":{"k-9a1be64e7f074b1c":[["江苏 2024 C类 行测#4"]]}};
